    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

long long smallestUnpayable(const int* coins0, int n) {
    int* coins = malloc(n * sizeof(int));
    memcpy(coins, coins0, n * sizeof(int));
    qsort(coins, n, sizeof(int), cmpInt);
    long long reach = 0;
    for (int i = 0; i < n; i++) {
